-- Normalized Schema: Requires expensive JOINs to display user orders and current addresses
CREATE TABLE users (user_id INT PRIMARY KEY, name VARCHAR(100));
CREATE TABLE addresses (address_id INT PRIMARY KEY, user_id INT, street VARCHAR(255));
CREATE TABLE orders (order_id INT PRIMARY KEY, user_id INT, total_amount DECIMAL(10,2));

-- Denormalized Schema: Optimized for read performance by duplicating user context and pre-aggregating totals
CREATE TABLE user_order_summary (
    order_id INT PRIMARY KEY,
    user_id INT,
    user_name VARCHAR(100),
    shipping_street VARCHAR(255),
    total_amount DECIMAL(10,2),
    last_modified TIMESTAMP
);
